#!/usr/bin/env node

import {
  CliHelpRequested,
  CliParseError,
  getProgramName,
  parseRequiredIntOptions,
} from "./lib/argparse-like.mjs";
import { isDirectedAcyclicGraph } from "./lib/dag-check.mjs";
import { DiGraph } from "./lib/digraph.mjs";
import { formatPythonBool } from "./lib/python-format.mjs";
import { TEST5_ARGUMENT_SPECS } from "./lib/test5-cli-spec.mjs";

function main() {
  const progName = getProgramName(process.argv[1]);
  const args = parseRequiredIntOptions(process.argv.slice(2), {
    progName,
    argumentSpecs: TEST5_ARGUMENT_SPES,
  });
  const graph = new DiGraph();

  graph.addEdgesFrom([
    [args.a, args.b],
    [args.b, args.c],
    [args.c, args.d],
    [args.d, args.e],
  ]);

  console.log(formatPythonBool(isDirectedAcyclicGraph(graph)));
}

try {
  main();
} catch (error) {
  if (error instanceof CliHelpRequested) {
    process.stdout.write(error.output);
    process.exitCode = 0;
  } else if (error instanceof CliParseError) {
    process.stderr.write(error.output);
    process.exitCode = 2;
  } else {
    throw error;
  }
}

