export function isDirectedAcyclicGraph(graph) {
  const indegreeByNode = new Map();

  for (const node of graph.nodes()) {
    indegreeByNode.set(node, 0);
  }

  for (const node of graph.nodes()) {
    for (const neighbor of graph.neighbors(node)) {
      indegreeByNode.set(neighbor, indegreeByNode.get(neighbor) + 1);
    }
  }

  const zeroIndegreeNodes = [];

  for (const [node, indegree] of indegreeByNode) {
    if (indegree === 0) {
      zeroIndegreeNodes.push(node);
    }
  }

  let visitedNodeCount = 0;

  for (let index = 0; index < zeroIndegreeNodes.length; index += 1) {
    const node = zeroIndegreeNodes[index];
    visitedNodeCount += 1;

    for (const neighbor of graph.neighbors(node)) {
      const nextIndegree = indegreeByNode.get(neighbor) - 1;
      indegreeByNode.set(neighbor, nextIndegree);

      if (nextIndegree === 0) {
        zeroIndegreeNodes.push(neighbor);
      }
    }
  }

  return visitedNodeCount === indegreeByNode.size;
}

